g.script:
      
      function createStar(cx, cy, size, duration, xSpeed, ySpeed) {
  let star = document.createElementNS("http://www.w3.org/2000/svg", "circle");
  star.setAttribute("cx", cx);
  star.setAttribute("cy", cy);
  star.setAttribute("r", size);
  star.setAttribute("fill", "white");
  star.setAttribute("opacity", (size / 7.5).toFixed(2));
  star.setAttribute("class", "star");
  star.style.setProperty("--x-speed", xSpeed + "px");
  star.style.setProperty("--y-speed", ySpeed + "px");
  star.style.setProperty("--duration", duration + "s");
  document.querySelector("g").appendChild(star);
}

const STAR_AMOUNT = 30;
for (let i = 0; i < STAR_AMOUNT; i++) {
  let xStart = (Math.random() * 1200).toFixed(2);
  let yStart = (Math.random() * 630).toFixed(2);
  let size = (Math.random() * 2 + 1.25).toFixed(2);
  let duration = ((Math.random() * 2 + 2)).toFixed(2); // Longer duration for smooth movement
  let xSpeed = ((Math.random() * 400 - 200)).toFixed(2); // Move farther
  let ySpeed = ((Math.random() * 200 - 100)).toFixed(2);
  createStar(xStart, yStart, size, duration, xSpeed, ySpeed);
}
